import os, json, re
import numpy as np

N = 26
SNAP_C = 'storage/noesis/latest_centers.txt'
SNAP_R = 'storage/noesis/latest_radii.txt'
P_K25   = 'storage/prometheus/exports_for_noesis/sota_620_top_k_slack_1e9.json'
P_K15   = 'storage/prometheus/exports_for_noesis/sota_620_top_k_slack_1e8.json'
OUT_JSON = 'storage/noesis/nmap/prometheus_620_crossing_examples.json'

def load_snapshot():
    c = np.loadtxt(SNAP_C, dtype=float).reshape(N,2)
    r = np.loadtxt(SNAP_R, dtype=float).reshape(N,)
    return c, r

def slacks(c, r):
    x = c[:,0]; y = c[:,1]
    s = {'xL': x - r, 'xR': 1 - x - r, 'yB': y - r, 'yT': 1 - y - r}
    diff = c[:,None,:] - c[None,:,:]
    dist = np.sqrt(np.sum(diff**2, axis=2))
    sp = dist - (r[:,None] + r[None,:])
    return s, sp

def read_pairs_json(path):
    S = set(); parsed = 0
    if not os.path.exists(path): return S, {'exists': False, 'parsed': 0}
    data = json.load(open(path,'r'))
    cand = []
    if isinstance(data, dict):
        for k in ('pairs','top_k','topk','data','list','items'):
            if k in data and isinstance(data[k], (list,tuple)): cand = data[k]; break
        if not cand and isinstance(data.get('0'), list): cand = list(data.values())
    elif isinstance(data, list):
        cand = data
    for it in cand:
        i=j=None
        if isinstance(it, dict):
            if 'pair' in it and isinstance(it['pair'], (list,tuple)) and len(it['pair'])>=2:
                i, j = it['pair'][0], it['pair'][1]
            else:
                i = it.get('i', it.get('disc_i', it.get('a')))
                j = it.get('j', it.get('disc_j', it.get('b')))
        elif isinstance(it, (list,tuple)) and len(it)>=2:
            i, j = it[0], it[1]
        try:
            i = int(i); j = int(j)
        except Exception:
            continue
        if 0 <= i < N and 0 <= j < N:
            S.add((min(i,j), max(i,j))); parsed += 1
        elif 1 <= i <= N and 1 <= j <= N:
            i0, j0 = i-1, j-1
            if 0 <= i0 < N and 0 <= j0 < N:
                S.add((min(i0,j0), max(i0,j0))); parsed += 1
    return S, {'exists': True, 'parsed': parsed}

def _orient(a,b,c):
    return (b[0]-a[0])*(c[1]-a[1]) - (b[1]-a[1])*(c[0]-a[0])
def _on_seg(a,b,p):
    return min(a[0],b[0])-1e-18 <= p[0] <= max(a[0],b[0])+1e-18 and min(a[1],b[1])-1e-18 <= p[1] <= max(a[1],b[1])+1e-18
def cross_strict(a,b,c,d):
    o1=_orient(a,b,c); o2=_orient(a,b,d); o3=_orient(c,d,a); o4=_orient(c,d,b)
    return (o1*o2<0) and (o3*o4<0)
def cross_incl(a,b,c,d):
    o1=_orient(a,b,c); o2=_orient(a,b,d); o3=_orient(c,d,a); o4=_orient(c,d,b)
    if (o1*o2<0) and (o3*o4<0): return True
    if abs(o1)<1e-18 and _on_seg(a,b,c): return True
    if abs(o2)<1e-18 and _on_seg(a,b,d): return True
    if abs(o3)<1e-18 and _on_seg(c,d,a): return True
    if abs(o4)<1e-18 and _on_seg(c,d,b): return True
    return False
def disjoint(p,q):
    i,j=p; k,l=q
    return (i!=k) and (i!=l) and (j!=k) and (j!=l)

def construct_packing():
    c, r = load_snapshot()
    s, sp = slacks(c, r)
    bmask_1e8 = ( (s['xL'] <= 1e-8+1e-12) | (s['xR'] <= 1e-8+1e-12) | (s['yB'] <= 1e-8+1e-12) | (s['yT'] <= 1e-8+1e-12) )

    prom_k25, _ = read_pairs_json(P_K25)
    prom_k15, _ = read_pairs_json(P_K15)
    inter_dual = sorted(list(prom_k25 & prom_k15))
    inter_dual_interior = [(i,j) for (i,j) in inter_dual if (not bmask_1e8[i]) and (not bmask_1e8[j])]

    motifs = []
    for a_idx in range(len(inter_dual_interior)):
        i,j = inter_dual_interior[a_idx]
        A,B = c[i], c[j]
        for b_idx in range(a_idx+1, len(inter_dual_interior)):
            k,l = inter_dual_interior[b_idx]
            if not disjoint((i,j),(k,l)): continue
            C,D = c[k], c[l]
            cs = cross_strict(A,B,C,D)
            ci = cross_incl(A,B,C,D)
            if cs or ci:
                # collect details
                motifs.append({
                    'pairs': [(i,j),(k,l)],
                    'cross_strict': bool(cs),
                    'cross_inclusive': bool(ci),
                    'slacks_before': {
                        f'{i}-{j}': float(sp[i,j]),
                        f'{k}-{l}': float(sp[k,l])
                    },
                    'boundary_flags@1e-8': {
                        str(i): bool(bmask_1e8[i]),
                        str(j): bool(bmask_1e8[j]),
                        str(k): bool(bmask_1e8[k]),
                        str(l): bool(bmask_1e8[l]),
                    }
                })
    out = {
        'prometheus_eval': 620,
        'dual_intersection_size': len(inter_dual),
        'dual_interior_size@1e-8': len(inter_dual_interior),
        'crossing_motifs': motifs[:10]  # cap for brevity
    }
    os.makedirs(os.path.dirname(OUT_JSON), exist_ok=True)
    with open(OUT_JSON, 'w') as f: json.dump(out, f, indent=2)
    print('PROM_620_CROSSING_JSON:', OUT_JSON, 'MOTIF_COUNT:', len(motifs))
    # Return baseline with tiny final shrink
    r_out = np.maximum(r - 1e-9, 1e-12)
    return c.astype(float), r_out.astype(float)
